#if UNITY_EDITOR
using NUnit.Framework;
using LastRail.Run;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
namespace LastRail.Tests.EditMode {public sealed class BSameRunSourceTests {
 [Test] public void SameRunBundleHasTypedOriginalReader(){Assert.NotNull(typeof(BDepartureAssignment).Assembly.GetType("LastRail.Run.BDepartureSourceBundle"));}
 internal static JObject Packet()=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-same-run-source-sample-20261006.json"))["packet"].DeepClone();
 internal static BDepartureSourceBundle Read(JObject p)=>BDepartureSourceBundle.Read(p.ToString(),(string)p["packetHash"],"a","LOCAL_NEW_B_PIN_19");
 static void Rehash(JObject p){var copy=(JObject)p.DeepClone();copy.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(copy).Substring(7);}
 [Test] public void OneOriginalBundlePreservesContextFullProfileNodeAndPreparedSlots(){var packet=Packet();var source=Read(packet);Assert.IsTrue(JToken.DeepEquals(packet,source.Capture()));Assert.NotNull(source.NativeNode);Assert.AreEqual((string)packet["originalCombatSource"]["contextId"],source.ContextId);Assert.AreEqual("LOCAL_CONTRACT_TEST_NOT_EXECUTOR",(string)source.OriginalCombatSource["profile"]["executorVersion"]);Assert.AreEqual("LOCAL_TX_ACTOR_NO_SPAWN",(string)source.OriginalCombatSource["rawProfiles"][0]["actorRef"]);source.RequireSameDeparture(source.NativeNode.Route);var prepared=source.PrepareFormation();Assert.AreEqual(4,prepared.Placement.RequireCar(4,"physical-4").PhysicalSlot);Assert.IsNull(prepared.Placement.AtPhysicalSlot(1));Assert.IsFalse(source.CanStart);Assert.Throws<InvalidOperationException>(()=>source.RequireRuntimeBinding());source.OriginalCombatSource["contextId"]="fake";Assert.IsTrue(JToken.DeepEquals(packet,source.Capture()));}
 [TestCase("context"),TestCase("profileHash"),TestCase("sourceHash"),TestCase("sourceRun"),TestCase("origin"),TestCase("assignment"),TestCase("nodeFence"),TestCase("missing"),TestCase("authority"),TestCase("risk"),TestCase("nativeOrigin"),TestCase("phase"),TestCase("unknown")]
 public void RehashedBundleCannotMixOriginalSourcesOrInventCapability(string kind){var p=Packet();switch(kind){case "context":p["originalCombatSource"]["contextId"]="foreign";break;case "profileHash":p["runtimeProfileHash"]=new string('0',64);break;case "sourceHash":p["combatSourceHash"]=new string('0',64);break;case "sourceRun":p["originalCombatSource"]["binding"]["runId"]="foreign";break;case "origin":p["originalOrigin"]["baseSnapshotHash"]=new string('0',64);break;case "assignment":p["assignment"]=BDepartureAssignmentTests.Packet();break;case "nodeFence":p["mapRevision"]=3;break;case "missing":p["missingSources"]=new JArray();break;case "authority":p["canStart"]=true;break;case "risk":p["originalRiskDefinition"]["policy"]["hp"]="fake";break;case "nativeOrigin":p["originalCombatSource"]["profile"]["definition"]["bNativeNodeOrigin"]["seedHash"]=new string('0',64);break;case "phase":p["phase"]="UNKNOWN";break;case "unknown":p["effectiveProfile"]=new JObject();break;}Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));}
 [Test] public void PreservesNullNodeWithExactDeclaredMissingInsteadOfBackfill(){var p=Packet();p["nativeNodeSource"]=JValue.CreateNull();((JArray)p["missingSources"]).Add("SELECTED_COMBAT_NODE");Rehash(p);var source=Read(p);Assert.IsNull(source.NativeNode);Assert.That(source.MissingSources,Does.Contain("SELECTED_COMBAT_NODE"));}
 [Test] public async Task ControllerPublishesBundleAndAssignmentAtomicallyFromOneOwner(){var source=Read(Packet());using(var c=new BRouteSessionController(source.AccountId,source.RunId)){var before=c.Capture();Assert.IsTrue(await c.ReadDepartureSourceBundleAsync(_=>Task.FromResult(source)));Assert.AreSame(source,c.DepartureSourceBundle);Assert.AreSame(source.Assignment,c.DepartureAssignment);c.PrepareDepartureFormation().RequireSource(source.Assignment);Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));Assert.ThrowsAsync<ArgumentException>(async()=>await c.ReadDepartureAssignmentAsync(_=>Task.FromResult(BDepartureAssignmentTests.Read(BDepartureAssignmentTests.Packet()))));Assert.AreSame(source,c.DepartureSourceBundle);}}
 [TestCase("Unbind"),TestCase("Bind"),TestCase("Dispose")]
 public async Task ControllerLifetimeRejectsLateBundleAndAssignmentTogether(string action){var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19");var pending=new TaskCompletionSource<BDepartureSourceBundle>();CancellationToken seen=default;var read=c.ReadDepartureSourceBundleAsync(ct=>{seen=ct;return pending.Task;});if(action=="Unbind")c.Unbind();else if(action=="Bind")c.Bind(_=>Assert.Fail("Late notification"));else c.Dispose();Assert.IsTrue(seen.IsCancellationRequested);pending.SetResult(Read(Packet()));Assert.IsFalse(await read);if(action!="Dispose"){Assert.IsNull(c.DepartureAssignment);Assert.IsNull(c.DepartureSourceBundle);}c.Dispose();}
 [Test] public async Task CallerCancellationAndCrossRunDoNotPublishBundle(){using(var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19"))using(var ct=new CancellationTokenSource()){var pending=new TaskCompletionSource<BDepartureSourceBundle>();var read=c.ReadDepartureSourceBundleAsync(_=>pending.Task,ct.Token);ct.Cancel();pending.SetResult(Read(Packet()));Assert.ThrowsAsync(Is.InstanceOf<OperationCanceledException>(),async()=>await read);Assert.IsNull(c.DepartureSourceBundle);Assert.IsNull(c.DepartureAssignment);}using(var c=new BRouteSessionController("a","LOCAL_B12_RUN")){Assert.ThrowsAsync<ArgumentException>(async()=>await c.ReadDepartureSourceBundleAsync(_=>Task.FromResult(Read(Packet()))));}}
 [Test] public async Task CancellationCallbackCannotReenterBundlePublication(){using(var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19")){var pending=new TaskCompletionSource<BDepartureSourceBundle>();Task<bool> reentered=null;CancellationTokenRegistration registration=default;try{var read=c.ReadDepartureSourceBundleAsync(ct=>{registration=ct.Register(()=>reentered=c.ReadDepartureSourceBundleAsync(_=>Task.FromResult(Read(Packet()))));return pending.Task;});c.Unbind();pending.SetResult(Read(Packet()));Assert.IsFalse(await read);Assert.ThrowsAsync<InvalidOperationException>(async()=>await reentered);Assert.IsNull(c.DepartureAssignment);Assert.IsNull(c.DepartureSourceBundle);}finally{registration.Dispose();}}}
 [Test] public async Task ControllerRejectsChangedFrozenRawSourceWhenMapAdvances(){var source=Read(Packet());var p=Packet();p["originalCombatSource"]["rawProfiles"][0]["hp"]["value"]["numerator"]="19";p["combatSourceHash"]=BDirectAttackInput.Digest(p["originalCombatSource"]).Substring(7);p["mapRevision"]=3;p["phase"]="READY";p["pendingEdgeId"]=JValue.CreateNull();p["nativeNodeSource"]=JValue.CreateNull();((JArray)p["missingSources"]).Add("SELECTED_COMBAT_NODE");Rehash(p);var modified=Read(p);using(var c=new BRouteSessionController("a",source.RunId)){Assert.IsTrue(await c.ReadDepartureSourceBundleAsync(_=>Task.FromResult(source)));Assert.ThrowsAsync<ArgumentException>(async()=>await c.ReadDepartureSourceBundleAsync(_=>Task.FromResult(modified)));Assert.AreSame(source,c.DepartureSourceBundle);Assert.AreSame(source.Assignment,c.DepartureAssignment);}}
}}
